use xiom.io;
fn show_menu() {
  io.println("=== Suite ===");
  io.println("1. Calculator");
  io.println("2. Guessing Game");
  io.println("3. Tip Calculator");
  io.println("0. Exit");
}

fn calc_add(a: Int, b: Int) -> Int { a + b }
fn guess_number() -> Int { 42 }
fn tip_amount(bill: Int, pct: Int) -> Int { bill * pct / 100 }

fn run_choice(choice: Int) {
  if choice == 1 {
    io.println(calc_add(5, 3).to_str());
  } else if choice == 2 {
    io.println(guess_number().to_str());
  } else if choice == 3 {
    io.println(tip_amount(100, 18).to_str());
  };
}

fn main() -> Int {
  show_menu();
  run_choice(1);
  run_choice(3);
  return 0;
}
